<script setup lang="ts">
import { Crown, LockKeyhole, LogOut, Pencil, ShieldCheck, UserPlus, UsersRound, X } from 'lucide-vue-next'
definePageMeta({middleware:'auth'});useHead({title:'Clube — ChessDuel'})
type Player={id:string;nickname:string;avatar_url:string|null;status:'online'|'offline'|'away'|'dnd'}
type Membership={id:string;user_id:string;role:'admin'|'member';status:'active'|'pending';user?:Player}
type Club={id:string;name:string;description:string;avatar_url:string|null;join_policy:'open'|'approval';member_count:number;creator_id:string;members:Membership[];pending_memberships:Membership[];viewer_membership:Membership|null;can_administer:boolean}
const auth=useAuthStore(),config=useRuntimeConfig(),route=useRoute(),club=ref<Club|null>(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),editOpen=ref(false),file=ref<File|null>(null)
const edit=reactive({name:'',description:'',join_policy:'approval' as 'open'|'approval'}),headers=computed(()=>({Authorization:`Bearer ${auth.token}`}))
function message(e:unknown){const data=(e as {data?:{message?:string;errors?:Record<string,string[]>}})?.data;return data?.message||Object.values(data?.errors||{}).flat()[0]||'Não foi possível concluir a operação.'}
async function load(){loading.value=true;error.value='';try{const data=await $fetch<{club:Club}>(`/api/clubs/${route.params.id}`,{baseURL:config.public.api.baseURL,headers:headers.value});club.value=data.club;useHead({title:`${data.club.name} — ChessDuel`});Object.assign(edit,{name:data.club.name,description:data.club.description,join_policy:data.club.join_policy})}catch(e){error.value=message(e)}finally{loading.value=false}}
async function action(path:string,method:'POST'|'PATCH'|'DELETE',success:string,body?:FormData){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await $fetch(path,{baseURL:config.public.api.baseURL,method,headers:headers.value,body});notice.value=success;await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
function join(){return action(`/api/clubs/${club.value!.id}/join`,'POST',club.value!.join_policy==='open'?'Você entrou no clube.':'Solicitação enviada.')}
function membership(m:Membership,verb:'approve'|'decline'|'promote'){const labels={approve:'Membro aprovado.',decline:'Solicitação recusada.',promote:'Membro promovido a administrador.'};return action(`/api/clubs/${club.value!.id}/memberships/${m.id}/${verb}`,'PATCH',labels[verb])}
function remove(m:Membership){const own=m.user_id===auth.user?.id;return action(`/api/clubs/${club.value!.id}/memberships/${m.id}`,'DELETE',own?'Você saiu do clube.':'Membro removido.')}
function onFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
async function save(){const body=new FormData();body.append('club[name]',edit.name);body.append('club[description]',edit.description);body.append('club[join_policy]',edit.join_policy);if(file.value)body.append('avatar',file.value);await action(`/api/clubs/${club.value!.id}`,'PATCH','Clube atualizado.',body);if(!error.value)editOpen.value=false}
onMounted(load)
</script>
<template><main class="club-page"><NuxtLink class="back" to="/social/clubs">← Todos os clubes</NuxtLink><p v-if="loading" class="panel state" role="status">Carregando clube…</p><p v-else-if="error&&!club" class="panel error" role="alert">{{ error }}</p><template v-else-if="club">
  <section class="hero panel"><ClubsClubAvatar :name="club.name" :avatar-url="club.avatar_url" :size="96"/><div><span class="policy"><LockKeyhole v-if="club.join_policy==='approval'" :size="15"/><UsersRound v-else :size="15"/>{{ club.join_policy==='open'?'Entrada aberta':'Entrada por aprovação' }}</span><h1>{{ club.name }}</h1><p>{{ club.description||'Este clube ainda não adicionou uma descrição.' }}</p><small>{{ club.member_count }} membro(s)</small></div><div class="hero-actions"><button v-if="!club.viewer_membership" class="primary" :disabled="busy" @click="join"><UserPlus :size="17"/>{{ club.join_policy==='open'?'Entrar':'Solicitar entrada' }}</button><span v-else-if="club.viewer_membership.status==='pending'" class="pending">Solicitação pendente</span><button v-if="club.can_administer" @click="editOpen=true"><Pencil :size="17"/>Editar</button><button v-if="club.viewer_membership?.status==='active'" :disabled="busy" @click="remove(club.viewer_membership)"><LogOut :size="17"/>Sair</button></div></section>
  <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="notice" class="feedback success" role="status">{{ notice }}</p>
  <section v-if="club.can_administer&&club.join_policy==='approval'" class="panel"><h2>Pedidos pendentes <span>{{ club.pending_memberships.length }}</span></h2><p v-if="!club.pending_memberships.length" class="empty">Nenhuma solicitação aguardando análise.</p><ul v-else class="people"><li v-for="m in club.pending_memberships" :key="m.id"><NuxtLink :to="`/user/${encodeURIComponent(m.user!.nickname)}`"><ProfilePresenceAvatar :name="m.user!.nickname" :avatar-url="m.user!.avatar_url" :status="m.user!.status"/><strong>{{ m.user!.nickname }}</strong></NuxtLink><div><button class="primary" :disabled="busy" @click="membership(m,'approve')">Aprovar</button><button :disabled="busy" @click="membership(m,'decline')">Recusar</button></div></li></ul></section>
  <section class="panel"><h2>Membros <span>{{ club.members.length }}</span></h2><ul class="people"><li v-for="m in club.members" :key="m.id"><NuxtLink :to="`/user/${encodeURIComponent(m.user!.nickname)}`"><ProfilePresenceAvatar :name="m.user!.nickname" :avatar-url="m.user!.avatar_url" :status="m.user!.status"/><span><strong>{{ m.user!.nickname }}</strong><small v-if="m.role==='admin'"><Crown :size="13"/>Administrador</small></span></NuxtLink><div v-if="club.can_administer&&m.user_id!==auth.user?.id"><button v-if="m.role==='member'" :disabled="busy" @click="membership(m,'promote')"><ShieldCheck :size="16"/>Promover</button><button :disabled="busy" @click="remove(m)">Remover</button></div></li></ul></section>
  <div v-if="editOpen" class="overlay" @click.self="editOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title" @keydown.esc="editOpen=false"><header><h2 id="edit-title">Editar clube</h2><button aria-label="Fechar" @click="editOpen=false"><X :size="20"/></button></header><form @submit.prevent="save"><label>Nome<input v-model="edit.name" required minlength="3" maxlength="80"></label><label>Descrição<textarea v-model="edit.description" rows="4" maxlength="1000"/></label><fieldset><legend>Política de entrada</legend><label><input v-model="edit.join_policy" type="radio" value="open">Aberta</label><label><input v-model="edit.join_policy" type="radio" value="approval">Por aprovação</label></fieldset><label>Novo avatar opcional<input type="file" accept="image/png,image/jpeg,image/webp" @change="onFile"></label><button class="primary" :disabled="busy">{{ busy?'Salvando…':'Salvar alterações' }}</button></form></section></div>
</template></main></template>
<style scoped>
.club-page{width:min(1000px,calc(100% - 2rem));margin:auto;padding:2rem 0 4rem;color:var(--text)}.back{display:inline-block;margin-bottom:1rem;color:var(--accent);font-weight:700;text-decoration:none}.panel{padding:1.35rem;margin-bottom:1rem;background:var(--surface);border:1px solid var(--border);border-radius:15px;box-shadow:var(--shadow)}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:1.3rem}.hero h1{margin:.35rem 0;font-size:clamp(1.8rem,5vw,2.7rem)}.hero p{margin:.35rem 0;color:var(--text-muted)}.hero small{color:var(--text-muted)}.policy{display:flex;align-items:center;gap:.35rem;color:var(--accent);font-size:.78rem;font-weight:750}.hero-actions{display:flex;align-items:flex-end;flex-direction:column;gap:.55rem}.pending{padding:.65rem;color:var(--text-muted);background:var(--surface-strong);border-radius:8px}h2{display:flex;align-items:center;gap:.6rem;margin:0 0 1rem;font-size:1.15rem}h2>span{padding:.12rem .45rem;color:var(--text-muted);background:var(--surface-strong);border-radius:99px;font-size:.75rem}.people{padding:0;margin:0;list-style:none}.people li{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 0;border-top:1px solid var(--border-subtle)}.people a{display:flex;align-items:center;gap:.8rem;color:var(--text);text-decoration:none}.people a>span{display:grid;gap:.2rem}.people small{display:flex;align-items:center;gap:.25rem;color:var(--accent)}.people li>div{display:flex;gap:.5rem}button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;padding:.68rem .85rem;color:var(--text);background:var(--surface-strong);border:1px solid var(--border);border-radius:8px;cursor:pointer}button:hover:not(:disabled){background:var(--surface-hover)}button.primary{color:var(--accent-ink);background:var(--accent);border-color:var(--accent)}button:disabled{opacity:.55}.state,.empty{text-align:center;color:var(--text-muted)}.feedback{padding:1rem;border-radius:10px}.error{color:var(--danger);background:var(--danger-soft)}.success{color:var(--success);background:var(--success-soft)}.overlay{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:1rem;background:rgb(0 0 0/60%)}.modal{width:min(550px,100%);padding:1.3rem;background:var(--surface);border:1px solid var(--border);border-radius:15px}.modal header{display:flex;justify-content:space-between}.modal h2{margin:0}.modal form{display:grid;gap:1rem;margin-top:1rem}.modal label{display:grid;gap:.4rem;color:var(--text-muted)}input,textarea{width:100%;padding:.75rem;color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:8px}.modal fieldset{display:flex;gap:1rem;padding:1rem;border:1px solid var(--border);border-radius:9px}.modal fieldset label{display:flex}.modal fieldset input{width:auto}@media(max-width:720px){.hero{grid-template-columns:auto 1fr}.hero-actions{grid-column:1/-1;align-items:stretch}.people li{align-items:flex-start;flex-direction:column}.people li>div{width:100%;justify-content:flex-end}}
</style>
